export default {"html":"<h2 id=\"simplified-form-syntax\" data-line=\"0\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#simplified-form-syntax\" aria-hidden=\"true\"></a> Simplified form syntax</h2>\n<p data-line=\"2\" class=\"code-line\">In Ionic 7, the syntax for components such as Input and Select was greatly simplified. Until now, form-focused components like <code>ion-input</code> and <code>ion-select</code> had to be used together with <code>ion-item</code> and <code>ion-label</code>. In Ionic 7, you no longer need to combine them that way.</p>\n<p data-line=\"4\" class=\"code-line\">v6:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"5\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#B392F0\"> fill</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"outline\"</span><span style=\"color:#E1E4E8\">&gt; </span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;Email:&lt;/</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt; </span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#B392F0\"> placeholder</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"hi@ionic.io\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#E1E4E8\">&gt; </span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">div</span><span style=\"color:#B392F0\"> slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"helper\"</span><span style=\"color:#E1E4E8\">&gt;Please enter a valid email address&lt;/</span><span style=\"color:#85E89D\">div</span><span style=\"color:#E1E4E8\">&gt; </span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"13\" class=\"code-line\">v7:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"14\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  label</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"Email:\"</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  placeholder</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"hi@ionic.io\"</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  fill</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"outline\"</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  helper-text</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"Please enter a valid email address\"</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"23\" class=\"code-line\">Beyond simpler markup, you get these benefits:</p>\n<ul data-line=\"25\" class=\"code-line\">\n<li data-line=\"25\" class=\"code-line\">Form controls are now associated with labels, which improves accessibility</li>\n<li data-line=\"26\" class=\"code-line\">Clearer APIs improve the developer experience.</li>\n<li data-line=\"27\" class=\"code-line\">(Ionic itself becomes simpler to maintain, which should mean fewer bugs over time).</li>\n</ul>\n<h2 id=\"basic-form-syntax-changes\" data-line=\"29\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#basic-form-syntax-changes\" aria-hidden=\"true\"></a> Basic form syntax changes</h2>\n<p data-line=\"31\" class=\"code-line\">Here are syntax changes for several form controls. You can still use <code>ion-item</code> in Ionic 7 even though it is no longer required—I recommend using <code>ion-item</code> inside <code>ion-list</code>.</p>\n<h2 id=\"ion-input\" data-line=\"33\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#ion-input\" aria-hidden=\"true\"></a> ion-input</h2>\n<p data-line=\"35\" class=\"code-line\">v6:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"36\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;Enter your name&lt;/</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">span</span><span style=\"color:#B392F0\"> slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"error\"</span><span style=\"color:#E1E4E8\">&gt;Please enter a name&lt;/</span><span style=\"color:#85E89D\">span</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"44\" class=\"code-line\">v7:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"45\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#B392F0\"> label</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"Enter your name\"</span><span style=\"color:#B392F0\"> error</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"Please enter a name\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"ion-textarea\" data-line=\"49\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#ion-textarea\" aria-hidden=\"true\"></a> ion-textarea</h2>\n<p data-line=\"51\" class=\"code-line\">v6:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"52\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#B392F0\"> fill</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"solid\"</span><span style=\"color:#B392F0\"> counter</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;Comments&lt;/</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-textarea</span><span style=\"color:#B392F0\"> maxlength</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"500\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-textarea</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"59\" class=\"code-line\">v7:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"60\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-textarea</span><span style=\"color:#B392F0\"> fill</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"solid\"</span><span style=\"color:#B392F0\"> counter</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#B392F0\"> maxlength</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"500\"</span><span style=\"color:#B392F0\"> label</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"Comments\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-textarea</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"ion-select\" data-line=\"64\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#ion-select\" aria-hidden=\"true\"></a> ion-select</h2>\n<p data-line=\"66\" class=\"code-line\">v6:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"67\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;Pick a color&lt;/</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-select</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">ion-select-option</span><span style=\"color:#B392F0\"> value</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"red\"</span><span style=\"color:#E1E4E8\">&gt;Red&lt;/</span><span style=\"color:#85E89D\">ion-select-option</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">ion-select-option</span><span style=\"color:#B392F0\"> value</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"blue\"</span><span style=\"color:#E1E4E8\">&gt;Blue&lt;/</span><span style=\"color:#85E89D\">ion-select-option</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">ion-select-option</span><span style=\"color:#B392F0\"> value</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"green\"</span><span style=\"color:#E1E4E8\">&gt;Green&lt;/</span><span style=\"color:#85E89D\">ion-select-option</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;/</span><span style=\"color:#85E89D\">ion-select</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"78\" class=\"code-line\">v7:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"79\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-select</span><span style=\"color:#B392F0\"> label</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"Pick a color\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-select-option</span><span style=\"color:#B392F0\"> value</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"red\"</span><span style=\"color:#E1E4E8\">&gt;Red&lt;/</span><span style=\"color:#85E89D\">ion-select-option</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-select-option</span><span style=\"color:#B392F0\"> value</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"blue\"</span><span style=\"color:#E1E4E8\">&gt;Blue&lt;/</span><span style=\"color:#85E89D\">ion-select-option</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-select-option</span><span style=\"color:#B392F0\"> value</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"green\"</span><span style=\"color:#E1E4E8\">&gt;Green&lt;/</span><span style=\"color:#85E89D\">ion-select-option</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">ion-select</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"ion-checkbox\" data-line=\"87\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#ion-checkbox\" aria-hidden=\"true\"></a> ion-checkbox</h2>\n<p data-line=\"89\" class=\"code-line\">v6:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"90\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-checkbox</span><span style=\"color:#B392F0\"> slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"start\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-checkbox</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;I agree to the terms and conditions&lt;/</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"97\" class=\"code-line\">v7:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"98\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-checkbox</span><span style=\"color:#E1E4E8\">&gt;I agree to the terms and conditions&lt;/</span><span style=\"color:#85E89D\">ion-checkbox</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"ion-radio\" data-line=\"102\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#ion-radio\" aria-hidden=\"true\"></a> ion-radio</h2>\n<p data-line=\"104\" class=\"code-line\">v6:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"105\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;Grapes&lt;/</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-radio</span><span style=\"color:#B392F0\"> slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"end\"</span><span style=\"color:#B392F0\"> value</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"grapes\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-radio</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"112\" class=\"code-line\">v7:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"113\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-radio</span><span style=\"color:#B392F0\"> value</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"grapes\"</span><span style=\"color:#E1E4E8\">&gt;Grapes&lt;/</span><span style=\"color:#85E89D\">ion-radio</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"advanced-layouts\" data-line=\"117\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#advanced-layouts\" aria-hidden=\"true\"></a> Advanced layouts</h2>\n<p data-line=\"118\" class=\"code-line\">Real forms often do not follow these basic patterns. As advanced examples, let us look at form controls in various layouts.</p>\n<h2 id=\"form-controls-without-a-visible-label\" data-line=\"120\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#form-controls-without-a-visible-label\" aria-hidden=\"true\"></a> Form controls without a visible label</h2>\n<p data-line=\"122\" class=\"code-line\">When no label is shown, use <code>aria-label</code> to indicate what the control is for.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"124\"><span class=\"line\"><span style=\"color:#a0aab5\">&lt;!-- The label is displayed in this case --&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#B392F0\"> label</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"Enter your name\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">&lt;!-- The label is not displayed in this case --&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#B392F0\"> aria-label</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"Enter your name\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"132\" class=\"code-line\">When design constraints mean you do not want a visible label, skip <code>label</code> and use <code>aria-label</code>.</p>\n<h2 id=\"form-controls-whose-label-is-not-adjacent\" data-line=\"135\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#form-controls-whose-label-is-not-adjacent\" aria-hidden=\"true\"></a> Form controls whose label is not adjacent</h2>\n<p data-line=\"137\" class=\"code-line\">Next, form controls whose label is not adjacent. Try building the layout below.</p>\n<p data-line=\"139\" class=\"code-line\"><a href=\"https://gyazo.com/9efd6cbd635f944f39601ddb3b243df0\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"https://i.gyazo.com/9efd6cbd635f944f39601ddb3b243df0.gif\" alt=\"Image from Gyazo\" class=\"md-img\" loading=\"lazy\"></a></p>\n<p data-line=\"141\" class=\"code-line\">The v6 markup looks like this (non-critical code omitted):</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"143\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#B392F0\"> class</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"add-remove\"</span><span style=\"color:#B392F0\"> lines</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"none\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#B392F0\"> slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"start\"</span><span style=\"color:#E1E4E8\">&gt;Quantity moved&lt;/</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-buttons</span><span style=\"color:#B392F0\"> slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"start\"</span><span style=\"color:#B392F0\"> tabindex</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"1\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">ion-button</span><span style=\"color:#B392F0\"> slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"icon-only\"</span><span style=\"color:#B392F0\"> (click)</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"remove()\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        &lt;</span><span style=\"color:#85E89D\">ion-icon</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"remove-circle-outline\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-icon</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;/</span><span style=\"color:#85E89D\">ion-button</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-buttons</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#B392F0\"> required</span><span style=\"color:#B392F0\"> tabindex</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"2\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">ion-buttons</span><span style=\"color:#B392F0\"> slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"end\"</span><span style=\"color:#B392F0\"> tabindex</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"1\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      &lt;</span><span style=\"color:#85E89D\">ion-button</span><span style=\"color:#B392F0\"> slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"icon-only\"</span><span style=\"color:#B392F0\"> (click)</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"add()\"</span><span style=\"color:#E1E4E8\">&gt;&lt;</span><span style=\"color:#85E89D\">ion-icon</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"add-circle-outline\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-icon</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-button</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;/</span><span style=\"color:#85E89D\">ion-buttons</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">ion-text</span><span style=\"color:#B392F0\"> slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"end\"</span><span style=\"color:#B392F0\"> i18n</span><span style=\"color:#E1E4E8\">&gt;units / 1 unit in stock&lt;/</span><span style=\"color:#85E89D\">ion-text</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"158\" class=\"code-line\">If you simply add a <code>label</code> attribute to <code>ion-input</code> to match Ionic 7 form syntax, the label appears immediately to the left of the input and the layout breaks. Instead, use <code>aria-labelledby</code> to associate a non-adjacent label with <code>ion-input</code>, like this:</p>\n<div class=\"code-block-container\"><div class=\"code-block-filename-container\"><span class=\"code-block-filename\">html</span></div><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"160\"><span class=\"line\"><span class=\"diff-prefix\"> </span><span> &lt;ion-item class=\"add-remove\" lines=\"none\"&gt;</span></span>\n<span class=\"line diff remove\"><span class=\"diff-prefix\">-</span><span>   &lt;ion-label slot=\"start\"&gt;Quantity moved&lt;/ion-label&gt;</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>   &lt;ion-label id=\"label-amount\" slot=\"start\"&gt;Quantity moved&lt;/ion-label&gt;</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   &lt;ion-buttons slot=\"start\" tabindex=\"1\"&gt;</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     &lt;ion-button slot=\"icon-only\" (click)=\"remove()\"&gt;</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>         &lt;ion-icon name=\"remove-circle-outline\"&gt;&lt;/ion-icon&gt;</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     &lt;/ion-button&gt;&lt;/ion-buttons&gt;</span></span>\n<span class=\"line diff remove\"><span class=\"diff-prefix\">-</span><span>     &lt;ion-input required tabindex=\"2\"&gt;&lt;/ion-input&gt;</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>     &lt;ion-input required tabindex=\"2\" aria-labelledby=\"label-amount\"&gt;&lt;/ion-input&gt;</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     &lt;ion-buttons slot=\"end\" tabindex=\"1\"&gt;</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>       &lt;ion-button slot=\"icon-only\" (click)=\"add()\"&gt;&lt;ion-icon name=\"add-circle-outline\"&gt;&lt;/ion-icon&gt;&lt;/ion-button&gt;</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     &lt;/ion-buttons&gt;</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     &lt;ion-text slot=\"end\" i18n&gt;units / 1 unit in stock&lt;/ion-text&gt;</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span> &lt;/ion-item&gt;</span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"177\" class=\"code-line\">You only add WAI-ARIA attributes. Easy.</p>\n<h3 id=\"combining-shadow-parts-components\" data-line=\"179\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#combining-shadow-parts-components\" aria-hidden=\"true\"></a> Combining Shadow Parts components</h3>\n<p data-line=\"181\" class=\"code-line\"><code>ion-input</code> and <code>ion-textarea</code> work with the approach above, but other form controls that render as Shadow DOM—such as <code>ion-select</code> and <code>ion-toggle</code>—cannot use <code>aria-labelledby</code> at this time. (Reference: <a href=\"https://github.com/ionic-team/ionic-framework/issues/26829#issuecomment-1438844711\" target=\"_blank\" rel=\"noopener noreferrer\">https://github.com/ionic-team/ionic-framework/issues/26829#issuecomment-1438844711</a> )</p>\n<p data-line=\"183\" class=\"code-line\">For those, use <code>aria-label</code> instead. See the example below.</p>\n<p data-line=\"185\" class=\"code-line\"><a href=\"https://gyazo.com/2052f558e4dd0ba2e3f707e21a3cbf3c\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"https://i.gyazo.com/2052f558e4dd0ba2e3f707e21a3cbf3c.gif\" alt=\"Image from Gyazo\" class=\"md-img\" loading=\"lazy\"></a></p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"187\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#B392F0\"> label</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"Purchase amount\"</span><span style=\"color:#B392F0\"> labelPlacement</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"fixed\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-select</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">      slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"end\"</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">      aria-label</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"currency\"</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">      placeholder</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"Currency unit\"</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      &lt;</span><span style=\"color:#85E89D\">ion-select-option</span><span style=\"color:#B392F0\"> *ngFor</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"let item of currencyCodes\"</span><span style=\"color:#B392F0\"> [value]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"item.code\"</span><span style=\"color:#E1E4E8\">&gt;{{ item.label }}&lt;/</span><span style=\"color:#85E89D\">ion-select-option</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;/</span><span style=\"color:#85E89D\">ion-select</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"200\" class=\"code-line\"><code>ion-input</code> shows its label on the left, so I set the <code>label</code> attribute on <code>ion-input</code>. The important part is <code>ion-select</code>: because it renders as Shadow DOM, use <code>aria-label</code> instead of <code>aria-labelledby</code>.</p>\n<p data-line=\"202\" class=\"code-line\">So markup like the following is wrong. Be careful.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"204\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#B392F0\"> position</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"fixed\"</span><span style=\"color:#B392F0\"> id</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"label-buy\"</span><span style=\"color:#E1E4E8\">&gt;Purchase amount&lt;/</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-button</span><span style=\"color:#E1E4E8\">&gt;Some component&lt;/</span><span style=\"color:#85E89D\">ion-button</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-select</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">      slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"end\"</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">      aria-labelledby</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"label-buy\"</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">      placeholder</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"Currency unit\"</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      &lt;</span><span style=\"color:#85E89D\">ion-select-option</span><span style=\"color:#B392F0\"> *ngFor</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"let item of currencyCodes\"</span><span style=\"color:#B392F0\"> [value]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"item.code\"</span><span style=\"color:#E1E4E8\">&gt;{{ item.label }}&lt;/</span><span style=\"color:#85E89D\">ion-select-option</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;/</span><span style=\"color:#85E89D\">ion-select</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"218\" class=\"code-line\">There is no label right next to <code>ion-select</code>, so you cannot set the label name with <code>ion-select[label]</code> (the order would swap). Also, because <code>ion-select</code> renders as Shadow DOM, you cannot point <code>aria-labelledby</code> at a label element. Avoid this layout if you can; when you cannot, set <code>aria-label</code> on <code>ion-select</code>.</p>\n<h3 id=\"combining-template-conditionals\" data-line=\"221\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#combining-template-conditionals\" aria-hidden=\"true\"></a> Combining template conditionals</h3>\n<p data-line=\"223\" class=\"code-line\"><a href=\"https://gyazo.com/7ca0ad0104354aa5b47819ce50e6ae30\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"https://i.gyazo.com/7ca0ad0104354aa5b47819ce50e6ae30.gif\" alt=\"Image from Gyazo\" class=\"md-img\" loading=\"lazy\"></a></p>\n<p data-line=\"225\" class=\"code-line\">The Angular syntax makes this a bit hard to read, but <code>*ngIf</code> is a conditional: when the condition is true, that DOM is rendered.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"227\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#B392F0\"> position</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"fixed\"</span><span style=\"color:#B392F0\"> id</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"label-year\"</span><span style=\"color:#E1E4E8\">&gt;Vintage year&lt;/</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ng-container</span><span style=\"color:#B392F0\"> *ngIf</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"year !== 0\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#B392F0\"> aria-labelledby</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"label-year\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">ion-text</span><span style=\"color:#B392F0\"> slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"end\"</span><span style=\"color:#E1E4E8\">&gt;year&lt;/</span><span style=\"color:#85E89D\">ion-text</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;/</span><span style=\"color:#85E89D\">ng-container</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-text</span><span style=\"color:#B392F0\"> *ngIf</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"year === 0\"</span><span style=\"color:#E1E4E8\">&gt;No vintage year (Non-Vintage)&lt;/</span><span style=\"color:#85E89D\">ion-text</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-checkbox</span><span style=\"color:#B392F0\"> aria-label</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"Non Vintage\"</span><span style=\"color:#B392F0\"> slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"end\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-checkbox</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"239\" class=\"code-line\">I want the label visible whether or not <code>ion-input</code> is present, so I use a real <code>ion-label</code> instead of <code>ion-input[label]</code>. On <code>ion-input</code>, I reference that label with <code>aria-labelledby=\"label-year\"</code>.<br>\nFor <code>ion-checkbox</code>, the label lives in Shadow DOM, so use <code>aria-label</code> instead of <code>aria-labelledby</code>. <code>aria-label</code> sets the label text directly on the element.</p>\n<h2 id=\"deferring-migration\" data-line=\"242\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#deferring-migration\" aria-hidden=\"true\"></a> Deferring migration</h2>\n<p data-line=\"244\" class=\"code-line\">Sometimes you think, \"This layout is hard with the new syntax—I want to change the design later!\" In that case, <code>legacy=true</code> explicitly marks that you have not migrated to the new syntax yet.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"246\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#B392F0\"> fill</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"outline\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;Email:&lt;/</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#B392F0\"> placeholder</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"hi@ionic.io\"</span><span style=\"color:#B392F0\"> legacy</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-input</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &lt;</span><span style=\"color:#85E89D\">div</span><span style=\"color:#B392F0\"> slot</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"helper\"</span><span style=\"color:#E1E4E8\">&gt;Please enter a valid email address&lt;/</span><span style=\"color:#85E89D\">div</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"254\" class=\"code-line\">It is a temporary workaround, but handy to remember.</p>\n<h2 id=\"summary\" data-line=\"256\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"258\" class=\"code-line\">Once you leave the basic patterns, things get a bit tricky. I think this order of thinking works:</p>\n<ol data-line=\"260\" class=\"code-line\">\n<li data-line=\"260\" class=\"code-line\">Label immediately to the left of the form control → <code>label</code></li>\n<li data-line=\"261\" class=\"code-line\">Label is not adjacent &amp;&amp; not Shadow DOM → <code>aria-labelledby</code></li>\n<li data-line=\"262\" class=\"code-line\">No label, or Shadow DOM → <code>aria-label</code></li>\n<li data-line=\"263\" class=\"code-line\">Still stuck → <code>legacy=true</code></li>\n</ol>\n<p data-line=\"265\" class=\"code-line\">The basic patterns are much easier to implement now, and that is a good thing.</p>\n<p data-line=\"267\" class=\"code-line\">See you next time.</p>\n","headings":[{"id":"simplified-form-syntax","text":"Simplified form syntax","level":2},{"id":"basic-form-syntax-changes","text":"Basic form syntax changes","level":2},{"id":"ion-input","text":"ion-input","level":2},{"id":"ion-textarea","text":"ion-textarea","level":2},{"id":"ion-select","text":"ion-select","level":2},{"id":"ion-checkbox","text":"ion-checkbox","level":2},{"id":"ion-radio","text":"ion-radio","level":2},{"id":"advanced-layouts","text":"Advanced layouts","level":2},{"id":"form-controls-without-a-visible-label","text":"Form controls without a visible label","level":2},{"id":"form-controls-whose-label-is-not-adjacent","text":"Form controls whose label is not adjacent","level":2},{"id":"combining-shadow-parts-components","text":"Combining Shadow Parts components","level":3},{"id":"combining-template-conditionals","text":"Combining template conditionals","level":3},{"id":"deferring-migration","text":"Deferring migration","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
